#!/usr/bin/env bash
set -euo pipefail

BRANCH="claude/kitchen-profiles-fix"

echo "==> Fetching latest main..."
git fetch origin main
git checkout main
git pull origin main

echo "==> Creating branch $BRANCH..."
git checkout -b "$BRANCH"

echo "==> Applying patch..."
base64 -d << 'PATCH_EOF' | git am

PATCH_EOF

echo "==> Installing deps..."
npm install

echo "==> Running snapshot..."
npm run snapshot

echo "==> Typecheck..."
npx tsc -b

echo "==> Lint..."
npm run lint

echo "==> Tests..."
npm test -- --run

echo "==> Build..."
npm run build

echo "==> Pushing branch..."
git push -u origin "$BRANCH"

echo ""
echo "Done! Open a PR at:"
echo "https://github.com/yoosuf0806/go-website/compare/main...$BRANCH"
